Given an array arr[] and a positive integer k, find the first negative integer for each window(contiguous subarray) of size k. If a window does not contain a negative, then print 0 for that window.Examples:  Input: arr[] = [-8, 2, 3, -6, 1] , k = 2Output: [-8, 0, -6, -6]Explanation: First negative integer for each window of size 2[-8,2] = -8, [2,3] = 0 (does not contain a negative integer), [3,-6] = -6, [-6,10] = -6Input: arr[] = [12, -1, -7, 8, -15, 30, 16, 28], k = 3Output: [-1, -1, -7, -15, -15, 0]Explanation: First negative integer for each window of size 3[ 12, -1, -7] = -1, [-1,-7, 8] = -1, [-7, 8, -15] = -7, [8, -15, 30] = -15, [-15, 30, 16] = -15, [30, 16, 28] = 0Try It YourselfTable of Content[Naive Approach] Nested Loops - O(n*k) time and O(1) space[Better Approach] Sliding Window with Deque technique - O(n) time and O(k) space[Expected Approach] Sliding Window with Index Tracking - O(n) time and O(1) space[Naive Approach] Using Nested Loops - O(n*k) time and O(1) spaceLoop through each window of size k and check its elements to find the first negative number. If found, print it; otherwise, print 0.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> firstNegInt(vector<int>& arr, int k) {
    vector<int> res;
    int n = arr.size();

    // Loop for each subarray(window) of size k
    for (int i = 0; i <= (n - k); i++) {
        bool found = false;

        // traverse through the current window
        for (int j = 0; j < k; j++) {

            // if a negative integer is found, then 
            // it is the first negative integer for 
            // the current window. Set the flag and break
            if (arr[i + j] < 0) {
                res.push_back(arr[i + j]);
                found = true;
                break;
            }
        }

        // if the current window does not contain 
        // a negative integer
        if (!found) {
            res.push_back(0);
        }
    }
    return res;
}

int main() {
    vector<int> arr = {12, -1, -7, 8, -15, 30, 16, 28};

    int k = 3;
    vector<int> res = firstNegInt(arr, k);
    for (int i = 0; i < res.size(); i++) {
        cout << res[i] << " ";
    }
    return 0;
}


